do
    local function targets(origin, radius)
        local out = {}
        local bases = workspace:FindFirstChild("SpawnedBases")
        if not bases then return out end
        local rar = not origin and multiSet("cs_rarity") or nil
        local zones = not origin and multiSet("cs_zones") or nil
        local muts = not origin and multiSet("cs_mut") or nil
        local dropped = origin ~= nil
        local now = os.clock()
        for _, base in ipairs(bases:GetChildren()) do
            local mut = base:GetAttribute("Mutation") or "NORMAL"
            local zoneOk = true
            if zones then
                local boss = baseBoss(base)
                zoneOk = boss ~= nil and zones[BOSS_AREA[boss]] == true
            end
            if zoneOk and (not muts or muts[mut]) then
                for _, ch in ipairs(base:GetChildren()) do
                    local ph
                    if ch.Name:sub(1, 4) == "Hen_" then
                        if ch:GetAttribute("EggHidden") ~= true then ph = ch:GetAttribute("Placeholder") end
                    elseif dropped and ch.Name:sub(1, 11) == "DroppedEgg_" then
                        ph = tonumber(ch.Name:sub(12))
                    end
                    local et = ch:GetAttribute("EggType")
                    local key = base.Name .. "#" .. tostring(ph)
                    if ph and et and (not rar or rar[EGG.rarity[et] or ""]) and not (S.skip[key] and S.skip[key] > now) then
                        local ok, piv = pcall(ch.GetPivot, ch)
                        if ok and (not origin or (piv.Position - origin).Magnitude <= radius) then
                            out[#out + 1] = { base = base.Name, ph = ph, inst = ch, key = key, tier = EGG.tier[et] or 0, mut = EGG.mutRank[mut] or 1, pos = piv.Position }
                        end
                    end
                end
            end
        end
        table.sort(out, function(a, b)
            if a.tier ~= b.tier then return a.tier > b.tier end
            if a.mut ~= b.mut then return a.mut > b.mut end
            return a.key < b.key
        end)
        return out
    end

    local function stillThere(t)
        if not t.inst.Parent then return false end
        if t.inst.Name:sub(1, 4) == "Hen_" and t.inst:GetAttribute("EggHidden") == true then return false end
        return true
    end

    local function tryGrab(t)
        local before = carried()
        local ok = invoke("AreaService", "PickupEgg", t.base, t.ph)
        if ok and waitUntil(function() return carried() > before end, 1.5) then
            S.stolen = S.stolen + 1
            S.last = "Last: grabbed " .. (EGG.name[t.inst:GetAttribute("EggType") or ""] or "egg")
            return true
        end
        return false
    end

    local function grab(t)
        if tryGrab(t) then return true end
        S.skip[t.key] = os.clock() + 15
        return false
    end

    local function grabAt(t)
        local spot = t.pos + Vector3.new(0, 3, 0)
        tp(spot)
        task.wait(0.25)
        for _ = 1, 6 do
            if not (RUNNING and on("cs_steal")) or not stillThere(t) then return false end
            tp(spot)
            if tryGrab(t) then return true end
            task.wait(0.25)
        end
        S.skip[t.key] = os.clock() + 15
        S.last = "Last: couldn't grab, trying another egg"
        return false
    end

    local lastFullWarn = 0
    local function deposit()
        local p = depositPos()
        if not p then return end
        tp(p)
        if not waitUntil(function() return carried() == 0 end, 4) and os.clock() - lastFullWarn > 20 then
            lastFullWarn = os.clock()
            notify(L["Couldn't deposit. Your plot may be full."])
        end
    end
    S.deposit = deposit

    local function stealCycle()
        if lp:GetAttribute("InRagdoll") or not root() then return end
        if S.paused() then
            if carried() > 0 then deposit() end
