                    for _, t in ipairs(targets(r.Position, (Opt.cs_aurarange and Opt.cs_aurarange.Value) or 25)) do
                        if carried() >= cap then break end
                        if stillThere(t) then pcall(grab, t) end
                    end
                end
            end
            task.wait(0.1)
        end
    end)
    task.spawn(function()
        while RUNNING do
            pcall(function()
                local night = nightLeft()
                local phase
                if night then
                    phase = (on("cs_nightpause") and "Night, paused for " or "Night, ends in ") .. fmtTime(night)
                else
                    local nn = RS:FindFirstChild("NextNightTime")
                    phase = "Day" .. ((nn and type(nn.Value) == "number") and (", night in " .. fmtTime(nn.Value)) or "")
                end
                local lines = { phase, string.format("Stolen: %d   Carrying: %d/%d", S.stolen, carried(), maxPickup()) }
                if S.last ~= "" then lines[#lines + 1] = S.last end
                status:SetText(table.concat(lines, "\n"))
            end)
            local now = os.clock()
            for k, v in pairs(S.skip) do if v < now then S.skip[k] = nil end end
            task.wait(1)
        end
    end)
end

do
    local function myEggs()
        local out = {}
        for _, e in ipairs(CollectionService:GetTagged("PlacedEgg")) do
            if e:GetAttribute("OwnerId") == lp.UserId then out[#out + 1] = e end
        end
        if #out == 0 then
            local plot = myPlot()
            if plot then
                for _, d in ipairs(plot:GetDescendants()) do
                    if d:IsA("Model") and d:GetAttribute("EggId") and d:GetAttribute("OwnerId") == lp.UserId then out[#out + 1] = d end
                end
            end
        end
        return out
    end
    local function plotSurface()
        local plot = myPlot()
        local s = plot and plot:FindFirstChild("PlotSurface", true)
        return (s and s:IsA("BasePart")) and s or nil
    end
    local function eggTools()
        local out = {}
        for _, cont in ipairs({ lp:FindFirstChildOfClass("Backpack"), lp.Character }) do
            for _, t in ipairs(cont and cont:GetChildren() or {}) do
                if t:IsA("Tool") and t:HasTag("EggTool") and t:GetAttribute("EntityId") then out[#out + 1] = t end
            end
        end
        return out
    end
    local function takenSpots()
        local out = {}
        for _, e in ipairs(myEggs()) do
            local ok, p = pcall(function() return e:GetPivot().Position end)
            if ok then out[#out + 1] = p end
        end
        for _, a in ipairs(CollectionService:GetTagged("PlacedAnimal")) do
            if a:GetAttribute("OwnerId") == lp.UserId then
                local ok, p = pcall(function() return a:GetPivot().Position end)
                if ok then out[#out + 1] = p end
            end
        end
        return out
    end
    local function freeSpot(surface, taken)
        local half = surface.Size / 2
        for x = -half.X + 4, half.X - 4, 5 do
            for z = -half.Z + 4, half.Z - 4, 5 do
                local p = (surface.CFrame * CFrame.new(x, half.Y + 1.5, z)).Position
                local free = true
                for _, q in ipairs(taken) do
                    if (Vector3.new(q.X, p.Y, q.Z) - p).Magnitude < 4.5 then free = false break end
                end
                if free then return p end
            end
        end
    end
    local toolRetry = {}
    local function placeEggs()
        local tools = eggTools()
        if #tools == 0 then return end
        local maxEggs = modifier("MaxEggs")
        local count = #myEggs()
        if maxEggs and count >= maxEggs then return end
        local surface = plotSurface()
        if not surface then return end
        local taken = takenSpots()
        for _, tool in ipairs(tools) do
            if not on("cs_place") or (maxEggs and count >= maxEggs) then break end
            local id = tool:GetAttribute("EntityId")
            if (toolRetry[id] or 0) <= os.clock() then
                local pos = freeSpot(surface, taken)
                if not pos then break end
                local ok = invoke("EggService", "PlaceEgg", id, CFrame.new(pos) * CFrame.Angles(0, math.pi / 2, 0))
                taken[#taken + 1] = pos
                if ok then count = count + 1 else toolRetry[id] = os.clock() + 15 end
            end
        end
    end

    local Eggs = Tabs.Pets:AddLeftGroupbox(L["Eggs"], "egg")
    Eggs:AddToggle("cs_place", { Text = L["Auto Place Eggs"], Default = false, Tooltip = L["Places eggs from your inventory."] })
    Eggs:AddToggle("cs_hatch", { Text = L["Auto Hatch Ready Eggs"], Default = false })
    Eggs:AddButton({ Text = L["Place All Now"], Func = function() task.spawn(placeEggs) end })
    local eggStatus = Eggs:AddLabel(L["Plot: -"], true)

    local Pets = Tabs.Pets:AddRightGroupbox(L["Brainrots"], "paw-print")
    Pets:AddToggle("cs_equipbest", { Text = L["Auto Equip Best"], Default = false })
    Pets:AddToggle("cs_offline", { Text = L["Auto Collect Offline Cash"], Default = false })
    Pets:AddToggle("cs_sellall", { Text = L["Auto Sell Inventory"], Default = false, Tooltip = L["Sells unlocked brainrots."] })
    Pets:AddButton({ Text = L["Equip Best Now"], Func = function() task.spawn(invoke, "AnimalService", "EquipBest") end })

    task.spawn(function()
        local retryAt, tpTried = {}, {}
        local lastPlace = 0
        while RUNNING do
            if on("cs_place") and os.clock() - lastPlace > 1 then
                lastPlace = os.clock()
                pcall(placeEggs)
            end
            if on("cs_hatch") then
                local now = workspace:GetServerTimeNow()
                for _, e in ipairs(myEggs()) do
                    if not on("cs_hatch") then break end
                    local st, du, id = e:GetAttribute("StartTime"), e:GetAttribute("Duration"), e:GetAttribute("EggId")
                    if id and st and du and not e:GetAttribute("IsHatching") and st + du <= now and (retryAt[id] or 0) <= os.clock() then
                        local ok = invoke("EggService", "HatchEgg", id)
                        if not ok then
                            retryAt[id] = os.clock() + 20
                            if not tpTried[id] and not S.busy and not S.farming() and carried() == 0 and e.Parent then
                                tpTried[id] = true
                                tp(e:GetPivot().Position + Vector3.new(0, 4, 0))
                                task.wait(0.15)
                                invoke("EggService", "HatchEgg", id)
                            end
                        end
                    end
                end
            end
            pcall(function()
                local tools = #eggTools()
                local maxEggs = modifier("MaxEggs")
                eggStatus:SetText(string.format(L["Plot: %d/%s   In inventory: %d"], #myEggs(), maxEggs and tostring(maxEggs) or "?", tools))
            end)
            task.wait(0.5)
        end
    end)
    task.spawn(function()
        local t = { eq = 0, off = 0, sell = 0 }
        while RUNNING do
            local now = os.clock()
            if on("cs_equipbest") and now - t.eq > 3 then t.eq = now invoke("AnimalService", "EquipBest") end
            if on("cs_offline") and now - t.off > 15 then t.off = now invoke("AnimalService", "CollectOfflineCash") end
            if on("cs_sellall") and now - t.sell > 10 then t.sell = now invoke("InventoryService", "SellAll") end
            task.wait(0.5)
        end
    end)

    local Clones = Tabs.Pets:AddRightGroupbox(L["Clones"], "users")
    Clones:AddDropdown("cs_area", { Values = AREA_LIST, Default = "Auto", Text = L["Clone Area"] })
    local function sendClones()
        local a = Opt.cs_area.Value
        if a == "Auto" then
            invoke("CloneService", "SetAutoTarget", true)
            notify(L["Clones on auto area"])
        else
            invoke("CloneService", "SetAutoTarget", false)
            local ok = invoke("CloneService", "SetTarget", a)
            notify(ok and (L["Clones sent to "] .. a) or (a .. L[" is locked or on cooldown"]))
        end
    end
    Clones:AddToggle("cs_keepauto", { Text = L["Keep Clones On Auto"], Default = false })
    Clones:AddButton({ Text = L["Send Clones"], Func = function() task.spawn(sendClones) end })
    Clones:AddButton({ Text = L["Recall Clones"], Func = function() task.spawn(invoke, "CloneService", "SetTarget", "idle") end })
    Clones:AddButton({ Text = L["Unlock Portal"], Func = function() task.spawn(invoke, "CloneService", "UnlockPortal") end })
    task.spawn(function()
        local last = 0
        while RUNNING do
            if on("cs_keepauto") and os.clock() - last > 10 then
                last = os.clock()
                local cc = controller("CloneController")
                local isAuto = false
                if cc then pcall(function() isAuto = cc:IsAutoTarget() end) end
                if not isAuto then invoke("CloneService", "SetAutoTarget", true) end
            end
            task.wait(1)
        end
    end)
end

