do
    local GS = _G.__CW_CSE_STATE or {}
    _G.__CW_CSE_STATE = GS
    GS.god = false
    GS.god3 = false
    if type(GS.orig) == "table" then
        for key, fn in pairs(GS.orig) do
            local cname, fname = key:match("^(.-)%.(.+)$")
            local c = cname and controller(cname)
            if c then c[fname] = fn or nil end
        end
    end
    GS.orig = {}
    if GS.origReport then
        local ac = controller("AreaController")
        if ac then ac._ReportCaught = GS.origReport end
        GS.origReport = nil
    end

    local function installHook()
        if GS.hooked3 then return end
        local hookmm = hookmetamethod or (getgenv and getgenv().hookmetamethod)
        local ncm = getnamecallmethod or (getgenv and getgenv().getnamecallmethod)
        if not (hookmm and ncm) then return end
        local caught = remote("AreaService", "RF", "BossCaught")
        if not caught then return end
        GS.hooked3 = true
        local cc = checkcaller or function() return false end
        local ncc = newcclosure or function(f) return f end
        local old
        old = hookmm(game, "__namecall", ncc(function(self, ...)
            if self == caught and _G.__CW_CSE_STATE and _G.__CW_CSE_STATE.god3 and not cc() and ncm() == "InvokeServer" then
                return nil
            end
            return old(self, ...)
        end))
    end
    local function setGod(v)
        GS.god3 = v
        if v then installHook() end
        local ac = controller("AreaController")
        if not ac then return end
        local key = "AreaController._ReportCaught"
        if v then
            if GS.orig[key] == nil then GS.orig[key] = rawget(ac, "_ReportCaught") or false end
            ac._ReportCaught = function() end
        elseif GS.orig[key] ~= nil then
            ac._ReportCaught = GS.orig[key] or nil
            GS.orig[key] = nil
        end
    end
    onClean(function() setGod(false) end)

    local G = Tabs.Farm:AddRightGroupbox(L["Semi God Mode"], "shield")
    G:AddToggle("cs_god", { Text = L["Semi God Mode / Semi Invincible"], Default = false, Tooltip = L["Bosses can't catch you most of the time."], Callback = function(v) setGod(v) end })
    G:AddToggle("cs_escape", { Text = L["Auto Escape When Chased"], Default = false, Tooltip = L["Sends you home when chased."] })
    G:AddToggle("cs_escapefull", { Text = L["Only Escape When Carry Is Full"], Default = false })

    task.spawn(function()
        local coolUntil = 0
        while RUNNING do
            if on("cs_escape") and not S.busy and os.clock() >= coolUntil and lp:GetAttribute("Chased") == true then
                local n = carried()
                if n > 0 and (not on("cs_escapefull") or n >= maxPickup()) then
                    S.busy = true
                    pcall(S.deposit)
                    S.busy = false
                    if carried() > 0 then coolUntil = os.clock() + 5 end
                end
            end
            task.wait(0.05)
        end
    end)

    local rush = {}
    local function travelTime(c, speed)
        local CU = M.CloneUtils
        if not CU then return 0 end
        local ok, t = pcall(function()
            local slot = CU.GetFormationCFrame(lp, c.slot)
            local path, from
            if c.state == "walking" then
                path = CU.GetWalkPath(lp, c.targetPosition)
                from = slot and slot.Position
            else
                path = CU.GetReturnPath(lp, c.slot, type(c.holding) == "table" and #c.holding > 0)
                from = c.targetPosition
            end
            return CU.GetMinimumTravelTime(CU.GetPathLength(path, from), speed)
        end)
        if not ok or type(t) ~= "number" or t ~= t or t > 1e6 then return 0 end
        return math.max(0, t)
    end
    local function rushStep()
        local cc = controller("CloneController")
        if not cc then return end
        local ok, data = pcall(function() return cc:GetData() end)
        if not ok or type(data) ~= "table" or type(data.Clones) ~= "table" then return end
        local speed = (type(data.Speed) == "number" and data.Speed > 0) and data.Speed or 16
        local now = workspace:GetServerTimeNow()
        local margin = (Opt.cs_rushmargin and Opt.cs_rushmargin.Value) or 0.2
        for key, c in pairs(data.Clones) do
            if type(c) == "table" and (c.state == "walking" or c.state == "returning") and type(c.stateStart) == "number" then
                local id = c.id or key
                local tag = tostring(id) .. ":" .. c.state .. ":" .. tostring(c.stateStart)
                local r = rush[tag]
                if not r then r = { n = 0, last = 0, eta = c.stateStart + travelTime(c, speed) + margin } rush[tag] = r end
                if now >= r.eta and r.n < 15 and os.clock() - r.last > 0.35 then
                    r.n = r.n + 1
                    r.last = os.clock()
                    task.spawn(invoke, "CloneService", c.state == "walking" and "CloneArrived" or "CloneReturned", id)
                end
            end
        end
    end
    local Cl = Tabs.Farm:AddRightGroupbox(L["Clone Rush"], "fast-forward")
    Cl:AddToggle("cs_rush", { Text = L["Clone Rush"], Default = false, Tooltip = L["Faster clone trips."] })
    Cl:AddSlider("cs_rushmargin", { Text = L["Safety Margin"], Default = 0.2, Min = 0, Max = 2, Rounding = 2, Suffix = "s" })
    task.spawn(function()
        local sweep = 0
        while RUNNING do
            if on("cs_rush") then pcall(rushStep) end
            if os.clock() - sweep > 30 then
                sweep = os.clock()
                local n = 0
                for _ in pairs(rush) do n = n + 1 end
                if n > 200 then rush = {} end
            end
            task.wait(0.2)
        end
    end)
end

